# coding: utf-8
from pathlib import Path
import json,html
r=Path(__file__).resolve().parent; p=json.loads((r/'pages.json').read_text())
flowdata=json.loads((r/'flows.json').read_text())
flows=[(x['title'],x['ids'],x['note']) for x in flowdata]
boards='\n'.join(f'''<article class="flow"><div><h2>{html.escape(t)}</h2><p>{html.escape(n)}</p></div><a href="flow-{i+1}.png" target="_blank"><img src="flow-{i+1}.png" alt="{html.escape(t)}流程效果图" loading="lazy"></a></article>''' for i,(t,ids,n) in sorted(enumerate(flows), key=lambda v: 0 if v[1][0]=="品牌与启动" else v[0]+1))
cards='\n'.join(f'''<article class="screen" data-search="{html.escape(x['id']+' '+x['title']+' '+x['group'],quote=True)}"><a href="screens/{x['id']}.png" target="_blank"><img loading="lazy" src="screens/{x['id']}.png" alt="{html.escape(x['title'])}"></a><h3>{html.escape(x['title'])}</h3><p>{html.escape(x['note'])}</p><details><summary>页面依据与去向</summary><p>{html.escape(x['source'])}</p><p>{html.escape(x['after'])}</p><p>范围：{html.escape(x['role'])}</p></details></article>''' for x in p)
css='''*{box-sizing:border-box}body{margin:0;background:#f3f5f9;color:#182536;font:16px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}::selection{background:#dce7fd}a{color:#2859bc;text-underline-offset:4px}a:focus-visible,button:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid #2859bc;outline-offset:4px}header,main{max-width:1500px;margin:auto;padding:36px}header{padding-top:64px}h1{font-size:40px;line-height:1.2;margin:0 0 20px;font-weight:650}p{color:#647184;max-width:850px}nav{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0 0}button{font:inherit;border:1px solid #b9c5d7;background:white;color:#182536;border-radius:8px;padding:10px 20px;cursor:pointer}button[aria-pressed=true]{background:#2859bc;color:white;border-color:#2859bc}.flow{margin-bottom:60px}.flow h2{font-size:24px;margin-bottom:8px}.flow img{display:block;width:100%;height:auto;border-radius:12px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:46px 30px}.screen img{display:block;width:100%;border-radius:14px}.screen h3{font-size:17px;margin:15px 0 6px}.screen p{font-size:14px;margin:5px 0}.screen details{font-size:12px;color:#647184}input{font:inherit;background:white;border:1px solid #b9c5d7;border-radius:8px;padding:12px 16px;width:min(500px,100%);margin-bottom:30px;caret-color:#2859bc}[hidden]{display:none!important}.notice{padding-top:20px;border-top:1px solid #d6dde7;font-size:14px}footer{padding:0 36px 45px;max-width:1500px;margin:auto;color:#647184;font-size:13px}@media(max-width:1000px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:700px){header,main{padding:24px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:30px 18px}h1{font-size:30px}.flow{overflow:auto}.flow img{min-width:850px}.flow h2{font-size:21px}}'''
(r/'index.html').write_text(f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>叮咚聊 · 设计预览</title><style>{css}</style><header><h1>叮咚聊 · 设计预览</h1><p>岩白与钴蓝。已选定「笑着聊」LOGO。先看品牌与启动页，再看关键流程，再看全量页面和状态。保留原有服务、数据及权限规则，调整信息层级、入口和操作反馈。</p><p class="notice">feature-newUI-5 · 静态设计评审 · 121 个原有页面/状态 + 26 个补充状态<br>人物、账号、日期、媒体和二维码均为设计示例。活动模块以当前本地实现为依据；图片不代表实机验收。</p><nav><button aria-pressed="true" id="flowButton">关键流程</button><button aria-pressed="false" id="allButton">全量页面 · 147</button><a href="overview.png" target="_blank">主页面总览</a></nav></header><main><section id="flows"><article class="flow"><h2>已选定 · 笑着聊</h2><p>使用 D 方案：微笑对话框，钴蓝与白色。启动、等待、连接与登录设计图已统一更新，正式应用资产尚未替换。</p><a href="brand/identity.png" target="_blank"><img src="brand/identity.png" alt="已选定的笑着聊LOGO与小尺寸对照"></a><details><summary>查看选型过程</summary><a href="brand/alternatives/comparison.png" target="_blank">四款候选对比（已选择 D）</a> · <a href="brand/archive-dual-d/identity.png" target="_blank">已否定的旧双口方案</a></details></article>{boards}</section><section id="all" hidden><label for="search">搜索页面名称或编号</label><br><input id="search" type="search" placeholder="例如：群发、投诉、登录"><div class="grid">{cards}</div><p id="empty" hidden>没有匹配的页面。</p></section></main><footer>应用代码实现已暂停。此目录只存放设计图、渲染脚本和评审说明。</footer><script>const f=document.querySelector('#flows'),a=document.querySelector('#all'),fb=document.querySelector('#flowButton'),ab=document.querySelector('#allButton');function show(all){{f.hidden=all;a.hidden=!all;fb.setAttribute('aria-pressed',String(!all));ab.setAttribute('aria-pressed',String(all))}}fb.onclick=()=>show(false);ab.onclick=()=>show(true);document.querySelector('#search').oninput=e=>{{let n=0;document.querySelectorAll('.screen').forEach(c=>{{c.hidden=!c.dataset.search.toLowerCase().includes(e.target.value.toLowerCase());if(!c.hidden)n++}});document.querySelector('#empty').hidden=n>0}};</script></html>''')
(r/'coverage.md').write_text('# 页面覆盖\n\n基线：feature-newUI-5 / a55a32f。121个原有页面/状态与25个补充状态。不是146条独立路由。\n\n|ID|设计状态|源页面|业务说明|\n|---|---|---|---|\n'+'\n'.join('|'+x['id']+'|'+x['title']+'|'+x['source']+'|'+x['note'].replace('|','／')+'|' for x in p)+'\n')
